function esNuevaPelicula(m) {
    // Si tiene fechaAgregado, verificar si han pasado menos de 7 días
    if (m.fechaAgregado) {
const agregado = new Date(m.fechaAgregado).getTime();
const ahora = Date.now();
const siete_dias = 7 * 24 * 60 * 60 * 1000;
return (ahora - agregado) < siete_dias;
    }
    // Fallback para películas antiguas sin fechaAgregado: nunca mostrar NUEVO
    return false;
}

function buildMovieCard(m) {
    const faved = isFav(m.id);
    const badgeNuevo = esNuevaPelicula(m) ? `<div class="badge-nuevo">NUEVO</div>` : '';
    return `<div class="movie-card" onclick="openDetailPage('${m.id}')">
${badgeNuevo}
<img class="movie-card-poster" src="${m.poster||m.image}" alt="${m.title}" loading="lazy">
<div class="movie-card-info">
    <div class="movie-card-title">${m.title}</div>
    <div class="movie-card-meta">
        <div class="movie-card-rating"><span class="star">★</span> ${m.rating||'?'}</div>
        <div class="movie-card-year">${m.year||''}</div>
    </div>
    <div class="movie-card-actions">
        <button class="movie-card-btn" onclick="event.stopPropagation();openDetailPage('${m.id}')">▶ Ver</button>
        <button class="movie-card-fav-btn ${faved?'active':''}" data-id="${m.id}" onclick="event.stopPropagation();toggleFavAndUpdate('${m.id}')">${faved?SVG_HEART_FULL:SVG_HEART_EMPTY}</button>
    </div>
</div>
    </div>`;
}

